'use strict';
let liquidXP=null;
function observeLiquidXP(level,xp,percent){
 const button=document.getElementById('buyXpBtn');if(!button)return;
 if(!liquidXP){const canvas=document.createElement('canvas');canvas.className='liquid-xp';canvas.setAttribute('aria-hidden','true');button.prepend(canvas);liquidXP={canvas,level,xp,view:percent/100,target:percent/100,from:percent/100,start:null,impact:0,flash:0,dots:[],raf:0};}
 const a=liquidXP,now=performance.now();if(level>a.level||level===a.level&&xp>a.xp){a.from=a.view;a.target=percent/100;a.start=now;a.impact=now+1000;if(level>a.level){a.view=1;a.from=1;a.flash=now+650;a.start=now+350;}for(let i=0;i<(level>a.level?24:12);i++)a.dots.push({start:now,life:320+(i%6)*55,x:(i+.5)/24,vx:Math.cos(i*2.4)*25,vy:-20-(i%4)*10});}else if(level<a.level||xp<a.xp){a.view=a.target=a.from=percent/100;a.dots=[];a.flash=0;}else if(a.start===null)a.view=a.target=percent/100;a.level=level;a.xp=xp;
 if(!a.raf&&!document.hidden)a.raf=requestAnimationFrame(drawLiquidXP);
}
function drawLiquidXP(now){const a=liquidXP;a.raf=0;const button=document.getElementById('buyXpBtn');if(document.hidden||document.getElementById('gameView').hidden){a.view=a.target;a.dots=[];return;}const r=button.getBoundingClientRect();if(r.width<=0||r.height<=0)return;const d=Math.min(devicePixelRatio||1,2),c=a.canvas.getContext('2d');if(a.canvas.width!==Math.round(r.width*d)||a.canvas.height!==Math.round(r.height*d)){a.canvas.width=Math.round(r.width*d);a.canvas.height=Math.round(r.height*d);}c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,r.width,r.height);if(a.start!==null&&now>=a.start){const t=Math.min(1,(now-a.start)/600);a.view=a.from+(a.target-a.from)*(1-(1-t)**3);if(t===1){a.start=null;a.view=a.target;}}
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){a.view=a.target;a.start=null;a.dots=[];a.flash=0;}const strength=Math.max(0,(a.impact-now)/1000),amp=5*(1+strength*1.8),y=r.height*(1-a.view),wave=x=>Math.sin(x*.06+now*.0024)*amp*.7+Math.sin(x*.115-now*.0014)*amp*.3;
 if(a.view>0){c.beginPath();c.moveTo(0,y+wave(0));for(let x=2;x<=r.width+2;x+=2)c.lineTo(x,y+wave(x));c.lineTo(r.width,r.height);c.lineTo(0,r.height);c.closePath();const g=c.createLinearGradient(0,y,0,r.height);g.addColorStop(0,'#c998f5');g.addColorStop(1,'#57307e');c.fillStyle=g;c.fill();c.beginPath();for(let x=0;x<=r.width;x+=2)x?c.lineTo(x,y+wave(x)):c.moveTo(x,y+wave(x));c.strokeStyle='#f1c5ff';c.lineWidth=1.5;c.stroke();for(let i=0;i<5;i++){const sy=y+12+(i*23+now*.008)%Math.max(22,r.height-y-16);if(sy<r.height-5){c.fillStyle='#ead7ff';c.fillRect(10+i*(r.width-20)/5,sy,2,2);}}}
 a.dots=a.dots.filter(p=>now-p.start<p.life);for(const p of a.dots){const t=(now-p.start)/1000;c.fillStyle='#fbddff';c.fillRect(Math.round(r.width*p.x+p.vx*t),Math.round(y+p.vy*t+35*t*t),3,3);}if(a.flash>now){c.fillStyle='rgba(240,200,255,'+Math.max(0,(a.flash-now)/1500)+')';c.fillRect(0,0,r.width,r.height);}if(!matchMedia('(prefers-reduced-motion: reduce)').matches)a.raf=requestAnimationFrame(drawLiquidXP);
}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&liquidXP){cancelAnimationFrame(liquidXP.raf);liquidXP.raf=0;liquidXP.dots=[];liquidXP.start=null;liquidXP.flash=0;liquidXP.impact=0;liquidXP.view=liquidXP.target;}else if(liquidXP)observeLiquidXP(liquidXP.level,liquidXP.xp,liquidXP.target*100);});
